using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_api"), Description("Fetches data from an external REST API endpoint.")]
    public static async Task<string> FetchApiAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The API path to call, e.g. /posts/1")] string path,
        CancellationToken cancellationToken)
    {
        var client = httpClientFactory.CreateClient("api");

        using var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text concisely.")]
    public static ChatMessage[] Execute(
        [Description("The text to summarize")] string text,
        [Description("Maximum number of sentences (default: 3)")] int maxSentences = 3)
    {
        return
        [
            new(Role.User,
                $"Summarize the following text in at most {maxSentences} sentences. " +
                $"Be concise and capture the key points.\n\n{text}")
        ];
    }
}

